/bin/bash -lc "mkdir -p src tests
cat > package.json <<'EOF'
{\"name\":\"logomocja\",\"version\":\"1.0.0\",\"type\":\"module\",\"scripts\":{\"build\":\"node build.mjs\",\"test\":\"node --test tests/*.test.js\"}}
EOF
cat > tests/interpreter.test.js <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { run } from '../src/interpreter.js';
test('żółw rysuje odcinek w kierunku północnym', () => {
  assert.deepEqual(run('np 10', '2d'), {segments:[{from:[0,0,0],to:[0,10,0],color:'#16866a',width:3}], error:null});
});
EOF
node --test tests/*.test.js"

