/bin/bash -lc "cat >> tests/interpreter.test.js <<'EOF'
test('błąd składni zatrzymuje cały program przed rysowaniem', () => {
  const result = run('np 20\\nnieznane', '2d');
  assert.equal(result.segments.length, 0);
  assert.equal(result.error.line, 2);
});
test('błąd wykonania zachowuje wcześniejszy rysunek', () => {
  const result = run('np 20\\nnp 1 / 0', '2d');
  assert.equal(result.segments.length, 1);
  assert.equal(result.error.line, 2);
});
test('obrót w przestrzeni prowadzi w górę', () => {
  const result = run('gora 90 np 10', '3d');
  assert.deepEqual(result.segments[0].to, [0,0,10]);
});
EOF
