/bin/bash -lc "cat >> tests/interpreter.test.js <<'EOF'
test('wyrażenia zachowują pierwszeństwo i łączność lewostronną', () => {
  assert.equal(run('np 20 - 5 - 3', '2d').segments[0].to[1], 12);
  assert.equal(run('np 2 + 3 * 4', '2d').segments[0].to[1], 14);
  assert.ok(run('np 10 -5', '2d').error);
});
test('procedura może być zdefiniowana po wywołaniu i używa lokalnych parametrów', () => {
  const source = 'figura 10\\noto figura ma: bok\\n powtorz 4 [np bok pw 90]\\njuż';
  const result = run(source, '2d');
  assert.equal(result.error, null);
  assert.equal(result.segments.length, 4);
  assert.deepEqual(result.segments[3].to, [0,0,0]);
});
test('czyść usuwa poprzednie odcinki, a dom rysuje powrót', () => {
  const result = run('np 10 czyść pw 90 np 10 dom', '2d');
  assert.equal(result.segments.length, 2);
  assert.deepEqual(result.segments[1].to, [0,0,0]);
});
test('nrpowt jest związany leksykalnie z powtórzeniem', () => {
  assert.ok(run('oto figura\\nnp nrpowt\\njuż\\npowtorz 2 [figura]', '2d').error);
  const result = run('powtorz 3 [np nrpowt]', '2d');
  assert.equal(result.segments.at(-1).to[1], 6);
});
test('zmienna bez wartości zgłasza błąd podczas wykonania', () => {
  const result = run('np 5 np bok niech bok 10', '2d');
  assert.equal(result.segments.length, 1);
  assert.equal(result.error.column, 9);
});
test('trójwymiarowe polecenia są niedostępne w 2D', () => {
  const result = run('np 10 gora 90', '2d');
  assert.equal(result.segments.length, 0);
  assert.equal(result.error.column, 7);
});
test('wszystkie przykłady wykonują się w swoich trybach', async () => {
  const {examples} = await import('../src/examples.js');
  for (const [,name,mode,,source] of examples) assert.equal(run(source,mode).error,null,name);
});
EOF
bun run test"

